 if(!special)return;
 if(v.special==='cerberus')setTimeout(()=>{if(current?.id!=='cerberus')return;roarUntil=clock.getElapsedTime()+4.7;hellGoal=1;playEffect('roar');setTimeout(()=>playEffect('gate'),900);if(!tour.active)setTimeout(()=>{if(current?.id==='cerberus'&&!tour.active)navigate('limbo',false,4)},5500)},sec*1000);
