let audio=null,audioOn=false,ambientNodes=[];function ensureAudio(){try{if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();audio.resume()}catch(e){audioOn=false}}
function tone(freq,dur,volume=.07,type='sine',slide=0){if(!audio||!audioOn)return;let o=audio.createOscillator(),g=audio.createGain(),now=audio.currentTime;o.type=type;o.frequency.setValueAtTime(freq,now);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(25,freq+slide),now+dur);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(volume,now+.02);g.gain.exponentialRampToValueAtTime(.0001,now+dur);o.connect(g).connect(audio.destination);o.start(now);o.stop(now+dur+.02)}
function playEffect(name){if(!audioOn)return;ensureAudio();if(name==='roar'){tone(87,.85,.14,'sawtooth',-48);setTimeout(()=>tone(54,1.1,.13,'sawtooth',-25),170);setTimeout(()=>tone(117,.9,.1,'triangle',-60),300)}else if(name==='gate'){tone(66,1.5,.075,'sawtooth',-29)}else if(name==='chime'){tone(523,1.6,.045,'sine');setTimeout(()=>tone(784,1.8,.04,'sine'),180);setTimeout(()=>tone(1046,2,.025,'sine'),370)}else tone(320,.2,.03,'sine')}
