function setQuality(q){quality=q;let mobile=innerWidth<650,cap=q==='Low'?1:q==='Medium'?1.5:2;renderer.setPixelRatio(Math.min(devicePixelRatio,cap));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=q==='High'&&!mobile;particles.forEach((v,i)=>v.g.visible=q!=='Low'||i%2===0);clouds.forEach((g,i)=>g.visible=q!=='Low'||i%3!==0);$('quality').value=q}
