function frame(){requestAnimationFrame(frame);let dt=Math.min(clock.getDelta(),.06),t=clock.getElapsedTime();if(!tour.paused)updateCamera(dt);updateTour(dt);updateTime(dt);updateAnimations(t,dt);updateAudio(t);if(!navTween)camera.lookAt(lookTarget);$('altitude').textContent=Math.round(camera.position.y)+' m';let inferred=camera.position.y<-95?'Hell':camera.position.y>280?'Heaven':'Earth';if(!current||current.realm==='Universe'){$('realm-name').textContent=inferred.toUpperCase();$('realm-dot').style.background=inferred==='Hell'?'#ff6b37':inferred==='Heaven'?'#f9e5a2':'#79d49d'}world.hell.visible=camera.position.y<75||current?.realm==='Universe';world.heaven.visible=camera.position.y>120||current?.realm==='Universe';renderer.render(scene,camera);frames++;frameSum+=dt;if(frameSum>1){$('fps').textContent=Math.round(frames/frameSum)+' FPS';frames=0;frameSum=0}}
